namespace ghidra.app.plugin.core.assembler;

using org.junit;

using ghidra.app.plugin.core.codebrowser;
using help.screenshot;

public class AssemblerPluginScreenShots : GhidraScreenShotGenerator {
	/* @Test */
	public void testCaptureAssembler()
    {
		setToolSize(1000, 800);

		positionListingTop(0x00405120);
		positionCursor(0x0040512e);
		AssemblerPlugin assemblerPlugin = addPlugin(tool, typeof(AssemblerPlugin));
		CodeViewerProvider codeViewer = waitForComponentProvider(typeof(CodeViewerProvider));

		performAction(assemblerPlugin.patchInstructionAction, codeViewer, true);

		AssemblyDualTextField input = assemblerPlugin.patchInstructionAction.input;
		runSwing(() => {
			input.auto.startCompletion(input.getOperandsField());
			input.auto.flushUpdates();
			input.auto.select(0);
		});

		captureProviderWithScreenShot(codeViewer);
	}
}
